import { expect, expectStatus, test } from "../../fixtures";

test.describe("vendor lifecycle", () => {
  test(
    "resubmitting without replacing the rejected document is refused",
    { tag: "@LIF-04" },
    async ({ apiAs, factory }) => {
      // Arrange
      const { vendor, documents } = await factory.vendorInReview();
      const reviewer = await apiAs("reviewer");
      const w9 = await factory.extraction(documents.w9.id);
      const rejected = await reviewer.post(`/api/extractions/${w9.id}/decision`, {
        data: { decision: "reject", note: "W-9 is unsigned" },
      });
      await expectStatus(rejected, 200);
      const member = await apiAs("member");

      // Act
      const response = await member.post(`/api/vendors/${vendor.id}/submit`);

      // Assert
      const body = await expectStatus<{ error: { code: string; missing_kinds: string[] } }>(response, 409);
      expect(body.error.code).toBe("documents_incomplete");
      expect(body.error.missing_kinds).toEqual(["w9"]);
    },
  );
});
